import type { AgentManifest } from '@tessera/compiler'

/** The first line of a generated file. `tessera agent-files` rewrites a file only if it starts with this, or with `--force`. */
export const GENERATED_MARKER =
  '<!-- Generated by `tessera agent-files`. Edit tessera.config.ts or the components, not this file. -->'

const list = (items: string[]) => items.map((i) => `- ${i}`).join('\n')

/**
 * A component as a model needs it to use it: what it is for, then what it takes (props, slots, variants) and what it
 * sends (each event, with what it carries). Written from the contract and the script, so it cannot drift from them.
 */
function componentLine(c: AgentManifest['components'][number]): string {
  const props = c.props.map((p) => (p.type === 'unknown' ? p.name : `${p.name} (${p.type})`))
  const slots = Object.entries(c.slots).map(([name, text]) => (text ? `${name} (${text})` : name))
  const variants = c.variants.map((v) => `${v.name}: ${v.values.join(' | ')}`)
  const events = Object.entries(c.events).map(([name, text]) =>
    text ? `@${name} (${text})` : `@${name}`,
  )
  const lines = [
    props.length && `props: ${props.join(', ')}`,
    slots.length && `slots: ${slots.join(', ')}`,
    variants.length && `variants: ${variants.join('; ')}`,
    events.length && `events: ${events.join(', ')}`,
    c.deprecated !== undefined && `deprecated${c.deprecated ? `: ${c.deprecated}` : ''}`,
  ].filter(Boolean)
  const head = `\`${c.name}\`${c.description ? ` — ${c.description}` : ''}`
  return [head, ...lines.map((l) => `  - ${l}`)].join('\n')
}

/** How to get a component the project does not have yet: copy it from the catalogue, never write one. */
const MORE_COMPONENTS = `These are the components this project has. For anything else, copy it from the Tessera UI catalogue instead of writing it: \`npx @pixelscriptio/tessera add --list\` shows what there is, and \`npx @pixelscriptio/tessera add Form TextField Select Checkbox Dialog Alert --yes\` copies components, and the ones they use, into \`system/components\`, where they are yours to read and edit. \`tessera add\` then updates this file. If it prints \`npm install <package>\` (Icon needs \`lucide\`), install the package only if the page shows an icon, and tell the person, because it adds a dependency. A component that uses \`Icon\` only for an optional icon works without it.
`

/** The APIs of the project, if it has any: what a call may use, and the tool that gives the details. */
function apisSection(manifest: AgentManifest, ticks: boolean): string {
  if (!manifest.apis.length) return ''
  const name = (n: string) => (ticks ? `\`${n}\`` : n)
  const lines = manifest.apis.map((a) => {
    const endpoints = a.endpoints.map((e) => `${e.method} ${e.path}`).join(', ')
    return `${name(a.name)}: ${endpoints || 'no description, so calls are not checked'}`
  })
  const how = ticks
    ? `\nCall them as \`<name>.get('/path')\`, \`<name>.post('/path')\` and so on (plain \`get\` is the \`default\` API). A call on an API that has a description is checked by the compiler; \`get_endpoint\` in the Tessera MCP server gives an endpoint's parameters and answer.\n`
    : ''
  return `\n## APIs\n\n${list(lines)}\n${how}`
}

/** The shared state of the project, if it has any: what a component may use, and how it may change it. */
function stateSection(manifest: AgentManifest, ticks: boolean): string {
  if (!manifest.state.length) return ''
  const name = (n: string) => (ticks ? `\`${n}\`` : n)
  const lines = manifest.state.map(
    (s) =>
      `${name(s.name)}: ${s.members.map((m) => (m.kind === 'function' ? `${m.name}()` : m.name)).join(', ') || 'nothing exported'}`,
  )
  const how = ticks
    ? `\nName a piece of state in a template or a script, with no import: \`{cart.count}\`, \`cart.add(item)\`. It is read-only outside its file: change it by calling the functions of its file, never by assigning (\`cart.items = []\` is an error). Put server data in \`get\`, not in state. \`get_state\` in the Tessera MCP server gives the members.\n`
    : ''
  return `\n## Shared state\n\n${list(lines)}\n${how}`
}

/** AGENTS.md: the rules an AI coding tool must follow in this project, and where the facts are. */
export function agentsMd(manifest: AgentManifest, options: { guide?: string } = {}): string {
  const governed = Object.keys(manifest.rules.governed)
  const themes = manifest.tokens.themes.map((t) => t.name)
  return `${GENERATED_MARKER}
# Working in this project

This is a Tessera project. The compiler rejects UI that is off the design system, so build from what exists
and check your work.

${options.guide ? `${options.guide.trim()}\n\n` : ''}## Rules

- Use the components below. Do not invent a component, and do not use a variant, slot or event a component does not declare.
- In \`<style>\`, write design tokens (\`$space.4\`, \`$color.surface.default\`), never raw values. These properties must use tokens: ${governed.join(', ') || '(none configured)'}.
- Prefer semantic tokens (\`color.text.default\`) to primitive ones (\`color.blue.600\`): semantic tokens change with the theme${themes.length ? ` (${themes.join(', ')})` : ''}.
- Style only the parts a component's contract documents. Text must keep a contrast ratio of at least ${manifest.rules.contrastMinimum}.
- Pages live in \`app/pages\`, a page may choose a layout (${manifest.routes.layouts.join(', ') || 'none'}), and links use \`<Link to="/path">\` with a route that exists.

## Check your work

Run \`npm run check\` after every change (the loop, above). \`npm run check -- --fix\` applies the fixes that cannot change how the page looks.

## Where the facts are

- \`node_modules/@pixelscriptio/tessera/dist/docs/llms-full.txt\`: the whole Tessera documentation as one Markdown file, offline. Search it (for a component, an error code or a feature) before guessing or going online; each page starts with a line \`<!-- page: path -->\`.
- \`.tessera/manifest.json\`: every component's contract, every token with its value in every theme, and the routes. Read it instead of guessing.
- \`npx @pixelscriptio/tessera mcp\`: a read-only MCP server for the same facts: search components, get a contract, resolve a raw value to a token, and validate a snippet.

## Components

${MORE_COMPONENTS}
${list(manifest.components.map(componentLine))}
${apisSection(manifest, true)}${stateSection(manifest, true)}`
}

/** llms.txt: the same facts as a short index for language models, in the llms.txt convention. */
export function llmsTxt(manifest: AgentManifest, name = 'This project'): string {
  return `# ${name}

> A Tessera project: components with contracts and design tokens, checked by the compiler. Build from the components and tokens listed in the manifest, and run \`npm run check\`.

## Facts

- [Manifest](.tessera/manifest.json): components, tokens (per theme), routes and rules, as JSON
- [Agent rules](AGENTS.md): what to do and not do in this project

## Components

${list(manifest.components.map((c) => `${c.name}: ${c.description ?? c.role}. Usage: \`${c.usage[0]}\``))}

## Routes

${list(manifest.routes.routes.map((r) => `${r.path} (${r.file})`)) || '- (none)'}
${apisSection(manifest, false)}${stateSection(manifest, false)}`
}
